import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-05-06","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-05-06","date":"2026-05-06T00:00:00.000Z","updated":"2026-05-14T00:00:00.000Z","tags":["RGW","lifecycle","cloud transition","多线程优化","object storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-06.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-06.md","lastUpdated":1780460162000}'),o={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-06.md"};function r(n,e,c,s,d,h){return t(),i("div",null,[...e[0]||(e[0]=[l('<h2 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h2><p>本次 RGW Refactoring Meeting 主要围绕两个议题展开：cloud transition 的异步删除支持，以及 lifecycle 处理的多线程优化方案。</p><h2 id="议题一-cloud-transition-异步删除支持-matthew" tabindex="-1">议题一：Cloud Transition 异步删除支持（Matthew） <a class="header-anchor" href="#议题一-cloud-transition-异步删除支持-matthew" aria-label="Permalink to &quot;议题一：Cloud Transition 异步删除支持（Matthew）&quot;">​</a></h2><p>Matthew 介绍了一个正在审查中的 PR，目标是为 cloud transition 功能添加对云端对象的异步删除调用支持。</p><p><strong>主要特性：</strong></p><ul><li>引入 FIFO Queue 机制，支持退避（back-off）策略</li><li>提供对应的 CLI 输出</li><li>该功能为 opt-in，默认不开启，保持 cloud tier 作为归档系统的基本定位</li></ul><p><strong>背景说明：</strong></p><p>部分运营商已将 cloud transition 的使用场景扩展到其原始设计范围之外，需要将 RGW 的删除操作同步到 cloud tier 端点。此 PR 在一定程度上补全了 cloud transition 的功能闭环。</p><p>由于 Samia 本周不在，Matthew 希望先收集社区的初步反馈。据悉 Samia 此前对该方案持开放态度。</p><h2 id="议题二-lifecycle-多线程处理方案-matthew" tabindex="-1">议题二：Lifecycle 多线程处理方案（Matthew） <a class="header-anchor" href="#议题二-lifecycle-多线程处理方案-matthew" aria-label="Permalink to &quot;议题二：Lifecycle 多线程处理方案（Matthew）&quot;">​</a></h2><p>Matthew 的团队针对 lifecycle 处理性能问题提出了两种竞争方案，核心目标是提升大桶（large bucket）的 lifecycle 处理速度。</p><h3 id="方案一-intra-rgw-多线程-单-daemon-内部并行" tabindex="-1">方案一：Intra-RGW 多线程（单 Daemon 内部并行） <a class="header-anchor" href="#方案一-intra-rgw-多线程-单-daemon-内部并行" aria-label="Permalink to &quot;方案一：Intra-RGW 多线程（单 Daemon 内部并行）&quot;">​</a></h3><ul><li>保持现有 on-disk 格式不变</li><li>新增约 200 行代码，配合部分重构</li><li>引入内存队列（in-memory queue），对大桶创建 fan-out 队列</li><li>空闲的 LC worker 完成自身调度桶后，进入 fan-out 队列协助处理长时运行的 lifecycle 任务</li><li>初步 PoC 结果：对长时运行的桶，处理速度提升 2~3 倍，且对 OSD 负载影响较小</li><li>实现相对简单，但仅限单 Daemon 范围内的并行</li></ul><h3 id="方案二-cross-rgw-多线程-跨-daemon-协同" tabindex="-1">方案二：Cross-RGW 多线程（跨 Daemon 协同） <a class="header-anchor" href="#方案二-cross-rgw-多线程-跨-daemon-协同" aria-label="Permalink to &quot;方案二：Cross-RGW 多线程（跨 Daemon 协同）&quot;">​</a></h3><ul><li>修改 on-disk 格式，使不同 RGW daemon 可独立处理同一个桶</li><li>利用 OMAP 在多个 RGW daemon 之间进行调度协调</li><li>可将集群中所有空闲 worker 纳入参与，潜力更大</li><li>实现复杂度高，存在调度竞态（race condition）风险，RADOS 写入开销也更大</li></ul><h3 id="社区讨论" tabindex="-1">社区讨论 <a class="header-anchor" href="#社区讨论" aria-label="Permalink to &quot;社区讨论&quot;">​</a></h3><p>与会者就当前瓶颈进行了讨论：</p><ul><li>当前 lifecycle 处理瓶颈更多在于对象操作 throttle，而非 CPU</li><li>建议考虑部署专用 RGW daemon 处理 lifecycle，配置更大的 throttle 上限</li><li>对于极端大桶场景（单桶 100~200 亿对象），跨 worker 拆分处理可能是必要的</li></ul><p><strong>实际用户场景：</strong></p><p>Matthew 分享了一个典型客户案例：某视频处理公司受法律合规约束，需在规定时间内删除特定视频，若 lifecycle 处理不及时将构成 SLA 违约。该客户预计单桶对象数将达到 150~200 亿，且每晚需批量过期大量对象。</p><p>目前团队正与该客户协商将数据分散到多个桶或多个区域端点，但客户应用改造存在一定阻力，因此短期内仍需从 RGW 侧提升 lifecycle 处理能力。</p><p><strong>结论：</strong></p><p>Casey 表示希望尽量避免拆分单桶处理逻辑，但承认在极端场景下可能确有必要，后续将与 Matt 团队进一步讨论最佳设计方案。</p><h2 id="公告" tabindex="-1">公告 <a class="header-anchor" href="#公告" aria-label="Permalink to &quot;公告&quot;">​</a></h2><p>Ceph 版本 Reef（Umbrella）的 feature freeze 将于本月底到来，有意合入新功能的开发者需在本月内完成相关工作。</p>',25)])])}const f=a(o,[["render",r]]);export{u as __pageData,f as default};
